intrinsic_skills.content:
var max_reveal = 2
var count = 0
while count < max_reveal:
	var prompt = "\"侦察\": （" + str(count + 1) + "/" + str(max_reveal) + ") 选择相邻地图块"
	var _candidates = player.get_current_block().get_blocks_in_range("medium")
	var _valid = []
	for _b in _candidates:
		target = _b
		if target.is_revealed() == false:
			_valid.append(_b)
		target = _b
	var _blocks = await player.choose_block_inline(_valid, prompt, 1)
	target = _blocks[0] if _blocks.size() > 0 else null
	if target == null:
		if count == 0:
			EventSystem.cancel(event)
			return
		break
	if count == 0:
		player.consume_action(1)
	target.reveal(false, player)
	count += 1

skills.content:
if event.trigger_name == "on_equip":
	player.increase_equipment_slot(1)
elif event.trigger_name == "on_unequip":
	player.decrease_equipment_slot(1)

var weapon = player.get_equipment("bear_trap")
player.discard("bear_trap", "equipment")
target.damage(4, player, "weapon_attack", weapon.equipment_card)

player.consume_action(1)
var weapon = player.get_equipment("bow")
target.damage(2, player, "weapon_attack", weapon.equipment_card)

player.consume_action(1)
var weapon = player.get_equipment("machete")
target.damage(3, player, "weapon_attack", weapon.equipment_card)

var max_steps = 3
var steps = 0
while steps < max_steps:
	var prompt = "\"摩托车\": （" + str(steps + 1) + "/3）选择目标地图块"
	var _candidates = player.get_current_block().get_blocks_in_range("medium")
	var _valid = []
	for _b in _candidates:
		target = _b
		if target != player.get_current_block():
			_valid.append(_b)
		target = _b
	var _blocks = await player.choose_block_inline(_valid, prompt, 1)
	target = _blocks[0] if _blocks.size() > 0 else null
	if target == null:
		if steps == 0:
			EventSystem.cancel(event)
			return
		break
	if steps == 0:
		player.consume_action(1)
		await player.consume_charge(player.get_equipment("motorcycle"), 1)
	var success = await player.move_to(target)
	if not success:
		break
	steps += 1

var list = game.get_all_players()
for i in list:
	i.decrease_hunger(1)

var list = game.get_all_discard_pile_equipments()
var _selected = await player.choose_card(1, list, null, "\"神通广大\": 选取一张装备牌")
if _selected.is_empty():
	EventSystem.cancel(event)
	return
var card = _selected[0]
var _targets = await player.choose_target(1, {"filter_target": "return target.is_player()", "filter_target_range": "infinity"}, "\"神通广大\": 选取置入装备牌的玩家")
if _targets.is_empty():
	EventSystem.cancel(event)
	return
target = _targets[0]
player.consume_action(1)
var original_pile = game.take_card_from_discard_piles(card)
var success = await target.equip(card)
if not success and original_pile != null:
	original_pile.add(card)

if event.trigger_name == "on_equip":
	player.add_sneak(2)
elif event.trigger_name == "on_unequip":
	player.reduce_sneak(2)

var piles = [game.get_scavenge_pile("red"), game.get_scavenge_pile("green"), game.get_scavenge_pile("blue")]
var valid_piles = []
for p in piles:
	if p != null and not p.is_empty():
		valid_piles.append(p)
if valid_piles.is_empty():
	EventSystem.cancel(event)
	return
var drawn_cards = []
var drawn_piles = []
while drawn_cards.size() < 3 and not valid_piles.is_empty():
	valid_piles.shuffle()
	var pile = valid_piles[0]
	var card = pile.draw()
	if card != null:
		drawn_cards.append(card)
		drawn_piles.append(pile)
	if pile.is_empty():
		valid_piles.erase(pile)
if drawn_cards.is_empty():
	EventSystem.cancel(event)
	return
var names = []
for c in drawn_cards:
	names.append(c.card_name)
game.log_message(LogColors.player(player.player_name) + " 展示了拾荒牌: " + ", ".join(names))
var selected = await player.choose_card(2, drawn_cards, null, "\"夜色掩护\": 选择要保留的牌", 0)
var event_scavenge = EventSystem.create_draw_scavenge_event(player, null, 0)
for i in range(drawn_cards.size()):
	var card = drawn_cards[i]
	var pile = drawn_piles[i]
	if selected.has(card):
		await player.draw_scavenge_card(card, pile, event_scavenge)
	else:
		player.discard(card)
